export async function createLikes(db: SurrealOpsLike, data: LikesCreateInput): Promise<Likes> {
  const content = Object.fromEntries(
    Object.entries(data).filter(([key]) => key !== "in" && key !== "out"),
  );
  return relateEdge(db, "likes", "user", "post", String(data.in), String(data.out), content) as Promise<Likes>;
}

