async function runTransaction<T>(
  db: SurrealLike,
  fn: (tx: ReturnType<typeof buildClientDelegates>) => Promise<T>,
): Promise<T> {
  const txn = await db.beginTransaction();
  const tx = buildClientDelegates(txn);
  try {
    const result = await fn(tx);
    await txn.commit();
    return result;
  } catch (err) {
    try {
      await txn.cancel();
    } catch {
      // ignore cancel errors after a failed transaction
    }
    throw err;
  }
}

async function openLiveSelect<T>(
  db: SurrealLike,
  sql: string,
  vars?: Record<string, unknown>,
): Promise<LiveHandle<T>> {
  const trimmed = sql.trim();
  if (!/^LIVE\s+SELECT\b/i.test(trimmed)) {
    throw new Error("$live: sql must be a LIVE SELECT statement");
  }
  const result = await db.query(trimmed, vars);
  const id = Array.isArray(result) ? result[0] : result;
  return db.liveOf<T>(id);
}

